// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface HolidayOut {
  holiday_id: number;
  holiday_date: string;
  name: string;
  notes: string | null;
  is_active: boolean;
  created_by: number | null;
  created_at: string;
  row_version: number;
}

export interface HolidaysIn {
  /** E.g. the year's gazetted list at once */
  holidays: HolidayIn[];
}

export interface HolidayIn {
  holiday_date: string;
  name: string;
  notes?: string | null;
}

export interface HolidayPatch {
  /** row_version you edited (else VERSION_CONFLICT) */
  expected_version?: number | null;
  holiday_date?: string | null;
  name?: string | null;
  notes?: string | null;
  /** false = withdraw the holiday (entries are never deleted) */
  is_active?: boolean | null;
}

/** Public holidays of a year (or a date range) — GET /api/v1/holidays (who may call: any logged-in user). */
export function listHolidays(query?: { year?: number | null; date_from?: string | null; date_to?: string | null; include_inactive?: boolean }): Promise<HolidayOut[]> {
  return api<HolidayOut[]>("GET", withQuery(`/holidays`, query), undefined);
}

/** Add public holidays (all or nothing) — POST /api/v1/holidays (who may call: holders of hr.holiday.manage). */
export function createHolidays(body: HolidaysIn): Promise<HolidayOut[]> {
  return api<HolidayOut[]>("POST", `/holidays`, body, { idempotent: true });
}

/** Rename, move or withdraw a public holiday — PATCH /api/v1/holidays/{holiday_id} (who may call: holders of hr.holiday.manage). */
export function updateHoliday(holiday_id: number, body: HolidayPatch): Promise<HolidayOut> {
  return api<HolidayOut>("PATCH", `/holidays/${holiday_id}`, body);
}
